function LadderCompetionLoadingDialog:InitComponent()
    self.listRoleSelf = {}
    self.listRoleImgSelf = {}
    self.listRoleInBattleSelf = {}
    self.listRoleEnemy = {}
    self.listRoleImgEnemy = {}
    self.listRoleInBattleEnemy = {}
    
    local _getImgComponent = function(rect)
        local transMask = rect.transform:Find("Mask")
        local transImgRole = rect.transform:Find("Mask/ImgRole")
        local rawImg
        if not isNull(transImgRole) then
            rawImg = KTool.GetOrAddComponent(transImgRole.gameObject, typeof(RawImageAlterable))
        end
        return rawImg, transMask
    end
    
    local _getSwitchImgComponent = function(rect)
        local transImg = rect.transform:Find("ImgBg")
        local switchImg
        if not isNull(transImg) then
            switchImg = KTool.GetOrAddComponent(transImg.gameObject, typeof(UISwitchImage))
        end
        return switchImg
    end
    
    local _fillRoleComponent = function(listRect, listImg, listSwitch, node)
        local roleImg, transMask = _getImgComponent(node)
        table.insert(listRect, transMask)
        table.insert(listImg, roleImg)
        local switchImg = _getSwitchImgComponent(node)
        table.insert(listSwitch, switchImg)
    end
    
    _fillRoleComponent(self.listRoleSelf, self.listRoleImgSelf, self.listRoleInBattleSelf, self.RoleSelf_1)
    _fillRoleComponent(self.listRoleSelf, self.listRoleImgSelf, self.listRoleInBattleSelf, self.RoleSelf_2)
    _fillRoleComponent(self.listRoleSelf, self.listRoleImgSelf, self.listRoleInBattleSelf, self.RoleSelf_3)
    _fillRoleComponent(self.listRoleSelf, self.listRoleImgSelf, self.listRoleInBattleSelf, self.RoleSelf_4)
    
    _fillRoleComponent(self.listRoleEnemy, self.listRoleImgEnemy, self.listRoleInBattleEnemy, self.RoleEnemy_1)
    _fillRoleComponent(self.listRoleEnemy, self.listRoleImgEnemy, self.listRoleInBattleEnemy, self.RoleEnemy_2)
    _fillRoleComponent(self.listRoleEnemy, self.listRoleImgEnemy, self.listRoleInBattleEnemy, self.RoleEnemy_3)
    _fillRoleComponent(self.listRoleEnemy, self.listRoleImgEnemy, self.listRoleInBattleEnemy, self.RoleEnemy_4)

    if not isNull(self.PlayerHeadNodeSelf) then
        self.PlayerHeadNodeSelf:Init()
    end

    if not isNull(self.PlayerHeadNodeEnemy) then
        self.PlayerHeadNodeEnemy:Init()
    end
end

