function LadderCompetionLoadingDialog:GetImgSegmentPath(valueSegment)
    local valueMap = {
        ["1"] = "e",
        ["2"] = "d",
        ["3"] = "c",
        ["4"] = "b",
        ["5"] = "a",
        ["6"] = "s",
    }
    return string.format("Arts/Icons/LadderCompetion/duel_settlement_position_%s.png", valueMap[valueSegment])
end

function LadderCompetionLoadingDialog:SetInfo()
    
    local segmentSelf = checkString(self.selfData.segment)
    self.ImgSegmentSelf:LoadSprite(self:GetImgSegmentPath(segmentSelf))
    local nameSelf = checkString(self.selfData.name)
    self.TextNameSelf.text = nameSelf
    local avatarSelf = checkNumber(self.selfData.avatar)
    local avatarFrameSelf = checkNumber(self.selfData.avatarFrame)
    if not isNull(self.PlayerHeadNodeSelf) then
        self.PlayerHeadNodeSelf.Env:FreshAvatarFrame(avatarSelf, avatarFrameSelf)
    end
    local scoreSelf = checkNumber(self.selfData.level)
    self.TextScoreSelf.text = string.format('LV.%d', scoreSelf)
    local cardsSelf = checkTable(self.selfData.cards)
    self:FillRoleImgNode(cardsSelf, self.listRoleSelf, self.listRoleImgSelf, self.listRoleInBattleSelf)
    local selfStar = checkNumber(self.selfData.subSegment)
    for i = 1, 5 do
        local child = self.SelfStarGroup.transform:GetChild(i - 1)
        KTool.SetActive(child, i <= selfStar)
    end
    
    local segmentEnemy = checkString(self.oppoData.segment)
    self.ImgSegmentEnemy:LoadSprite(self:GetImgSegmentPath(segmentEnemy))
    local nameEnemy = checkString(self.oppoData.name)
    self.TextNameEnemy.text = nameEnemy
    local avatarEnemy = checkNumber(self.oppoData.avatar)
    local avatarFrameEnemy = checkNumber(self.oppoData.avatarFrame)
    if not isNull(self.PlayerHeadNodeEnemy) then
        self.PlayerHeadNodeEnemy.Env:FreshAvatarFrame(avatarEnemy, avatarFrameEnemy)
    end
    local scoreEnemy = checkNumber(self.oppoData.level)
    self.TextScoreEnemy.text = string.format('LV.%d', scoreEnemy)
    local cardsEnemy = checkTable(self.oppoData.cards)
    self:FillRoleImgNode(cardsEnemy, self.listRoleEnemy, self.listRoleImgEnemy, self.listRoleInBattleEnemy)
    local enemyStar = checkNumber(self.oppoData.subSegment)
    for i = 1, 5 do
        local child = self.EnemyStarGroup.transform:GetChild(i - 1)
        KTool.SetActive(child, i <= enemyStar)
    end
    --self:UpdateTurnInfo()
end

