function LadderCompetionLoadingDialog:FillRoleImgNode(listCards, listCardNode, listCompImg, listCompSwitchImg)
    -- print("->111:", table.dump(listCardNode), table.dump(listCompImg), table.dump(listCompSwitchImg))
    if isNull(listCards) or table.count(listCards) <= 0 then return end
    for index, card in ipairs(listCards) do
        local cardSkin = checkNumber(card.cardSkin)
        local cardSkinVo = CfUtils.GetCfVo(AutoIds.IdSetting113, "CardSkinVo", cardSkin)
        local path = checkString(cardSkinVo.cardHeadList)
        listCompImg[index]:LoadSprite(path)
        listCompSwitchImg[index].Status = 2
        KTool.SetActive(listCardNode[index].gameObject, true)
    end
end

function LadderCompetionLoadingDialog:__Progress(value)
    value = math.min(value, 1)
    self._nowProgress = value
    self:SetUIProcess(value)
end

function LadderCompetionLoadingDialog:SetUIProcess(value)
    local progress = math.floor(checkNumber(value * 100))
    local _string = string.format("%0.1f", progress)
    self.MyProcess.value = value
    self.MyProcessTxt.text = _string .. "%"
    value = math.min(0.99, value)
    self.EnemyProcess.value = value
    self.EnemyProcessTxt.text = string.format("%0.1f", math.floor(checkNumber(value * 100))) .. "%"
end

function LadderCompetionLoadingDialog:Progress(value)
    value = value / 100
    self.targetValue = value
    local nowValue = self._nowProgress or 0
    if nowValue >= value then return end
    if value >= 1 then
        self.targetSpeed = (value - nowValue) / 0.01
    else
        self.targetSpeed = (value - nowValue) / 0.9--1秒到达
    end
end

return LadderCompetionLoadingDialog